18	export const isRoamSemanticSearchEnabled = (): boolean =>
19	  window.roamAlphaAPI.data.semanticSearchEnabled();
20	
21	const runMiniSearchSafely = (
22	  runMiniSearch: () => ScoredSearchResult[],
23	): ScoredSearchResult[] => {
24	  try {
25	    return runMiniSearch();
26	  } catch {
27	    return [];
28	  }
29	};
