31	export const searchDiscourseNodes = async ({
32	  nodeTypes,
33	  query,
34	  resultsByUid,
35	  runMiniSearch,
36	}: {
37	  nodeTypes: DiscourseNode[];
38	  query: string;
39	  resultsByUid: Map<string, SearchResult>;
40	  runMiniSearch: () => ScoredSearchResult[];
41	}): Promise<ScoredSearchResult[]> => {
42	  const trimmedQuery = query.trim();
43	  if (!trimmedQuery) return [];
44	
45	  if (!isRoamSemanticSearchEnabled()) {
46	    return runMiniSearchSafely(runMiniSearch);
47	  }
48	
49	  try {
50	    const providerResult = await runRoamSemanticSearch({
51	      nodeTypes,
52	      query: trimmedQuery,
53	    });
54	    const semanticResults = providerResult.filteredResults.map((item, index) =>
55	      toScoredSearchResultFromSemantic({
56	        uid: item.uid,
57	        title: item.text,
58	        type: item.type,
59	        nodeTypeLabel: item.nodeTypeLabel,
60	        score: item.score ?? 0,
61	        rank: index,
62	        resultsByUid,
63	      }),
64	    );
65	
66	    if (
67	      providerResult.filteredResultCount >=
68	      SEMANTIC_SEARCH_MIN_DISCOURSE_RESULTS
69	    ) {
70	      return semanticResults;
71	    }
72	
73	    return combineSemanticAndMiniSearchResults({
74	      semantic: semanticResults,
75	      miniSearch: runMiniSearchSafely(runMiniSearch),
76	    });
77	  } catch {
78	    return runMiniSearchSafely(runMiniSearch);
79	  }
80	};

